package com.iiop.maintenance.service;
import cn.dev33.satoken.stp.StpUtil;import com.baomidou.mybatisplus.core.metadata.IPage;import com.baomidou.mybatisplus.core.toolkit.Wrappers;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.iiop.common.api.*;import com.iiop.common.exception.BizException;import com.iiop.common.mq.InspectionAbnormalEvent;import com.iiop.maintenance.client.AuthClient;import com.iiop.maintenance.client.AuthClient.NotificationRequest;import com.iiop.maintenance.domain.MaintenanceDtos.*;import com.iiop.maintenance.domain.MaintenanceModels.*;import com.iiop.maintenance.mapper.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import org.slf4j.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class MaintenanceService {
 private static final Logger log=LoggerFactory.getLogger(MaintenanceService.class);private final AlarmMapper alarms;private final DefectMapper defects;private final WorkOrderMapper orders;private final WorkOrderLogMapper logs;private final MaintenanceRecordMapper records;private final AcceptanceMapper acceptances;private final AuthClient auth;
 public MaintenanceService(AlarmMapper a,DefectMapper d,WorkOrderMapper o,WorkOrderLogMapper l,MaintenanceRecordMapper r,AcceptanceMapper ac,AuthClient auth){alarms=a;defects=d;orders=o;logs=l;records=r;acceptances=ac;this.auth=auth;}
 @Transactional public void consumeAbnormal(InspectionAbnormalEvent e){if(e==null||e.abnormalId()==null)return;if(defects.selectCount(Wrappers.<Defect>lambdaQuery().eq(Defect::getSourceType,"INSPECTION_ABNORMAL").eq(Defect::getSourceId,e.abnormalId()))>0)return;Defect d=new Defect();d.setDefectCode(code("DEF"));d.setDeviceId(e.deviceId());d.setSourceType("INSPECTION_ABNORMAL");d.setSourceId(e.abnormalId());d.setTitle(e.title());d.setDescription("巡检异常自动生成缺陷");d.setSeverity(e.severity());d.setReportedAt(e.occurredAt());d.setStatus("OPEN");try{defects.insert(d);}catch(DuplicateKeyException x){log.info("忽略重复巡检异常消息 abnormalId={}",e.abnormalId());}}
 public PageResult<Alarm> alarms(long p,long s){IPage<Alarm>x=alarms.selectPage(new Page<>(p,Math.min(s,100)),Wrappers.<Alarm>lambdaQuery().orderByDesc(Alarm::getOccurTime));return page(x);}public Alarm alarm(Long id){Alarm v=alarms.selectById(id);if(v==null)throw notFound("告警不存在");return v;}
 @Transactional public Alarm alarmStatus(Long id,String action){Alarm a=alarm(id);if("acknowledge".equals(action)){if(!"ACTIVE".equals(a.getStatus()))throw conflict("只有活动告警可以确认");a.setStatus("ACKNOWLEDGED");}else if("close".equals(action)){if(!Set.of("ACTIVE","ACKNOWLEDGED","RECOVERED").contains(a.getStatus()))throw conflict("告警不能关闭");a.setStatus("CLOSED");}else throw bad("告警操作不正确");alarms.updateById(a);return a;}
 public PageResult<Defect> defects(long p,long s,String status,String severity,Long deviceId,String sourceType){IPage<Defect>x=defects.selectPage(new Page<>(p,Math.min(s,100)),Wrappers.<Defect>lambdaQuery().eq(status!=null,Defect::getStatus,status).eq(severity!=null,Defect::getSeverity,severity).eq(deviceId!=null,Defect::getDeviceId,deviceId).eq(sourceType!=null,Defect::getSourceType,sourceType).orderByDesc(Defect::getReportedAt));return page(x);}public Defect defect(Long id){Defect v=defects.selectById(id);if(v==null)throw notFound("缺陷不存在");return v;}
 @Transactional public Defect confirmDefect(Long id){requireDefectActor();defect(id);if(defects.update(null,Wrappers.<Defect>lambdaUpdate().eq(Defect::getId,id).eq(Defect::getStatus,"OPEN").set(Defect::getStatus,"CONFIRMED"))!=1)throw conflict("缺陷状态已变化");return defect(id);}
 @Transactional public Defect closeDefect(Long id){requireDefectActor();defect(id);if(defects.update(null,Wrappers.<Defect>lambdaUpdate().eq(Defect::getId,id).eq(Defect::getStatus,"RESOLVED").set(Defect::getStatus,"CLOSED"))!=1)throw conflict("缺陷状态已变化");return defect(id);}
 public PageResult<WorkOrder> orders(long p,long s,String status,String priority,Long deviceId,Long assigneeUserId){var q=Wrappers.<WorkOrder>lambdaQuery().eq(status!=null,WorkOrder::getStatus,status).eq(priority!=null,WorkOrder::getPriority,priority).eq(deviceId!=null,WorkOrder::getDeviceId,deviceId).eq(assigneeUserId!=null,WorkOrder::getAssigneeUserId,assigneeUserId);if(restrictedMaintainer()){Long u=current();q.and(w->w.eq(WorkOrder::getAssigneeUserId,u).or(x->x.eq(WorkOrder::getCreatorUserId,u).eq(WorkOrder::getStatus,"PENDING")));}IPage<WorkOrder>x=orders.selectPage(new Page<>(p,Math.min(s,100)),q.orderByDesc(WorkOrder::getCreatedAt));return page(x);}public WorkOrder order(Long id){WorkOrder v=orders.selectById(id);if(v==null)throw notFound("工单不存在");return v;}
 public WorkOrderDetail detail(Long id){WorkOrder o=order(id);requireVisible(o);return new WorkOrderDetail(o,logs.selectList(Wrappers.<WorkOrderLog>lambdaQuery().eq(WorkOrderLog::getWorkOrderId,id).orderByAsc(WorkOrderLog::getCreatedAt)),records.selectList(Wrappers.<MaintenanceRecord>lambdaQuery().eq(MaintenanceRecord::getWorkOrderId,id)),acceptances.selectList(Wrappers.<Acceptance>lambdaQuery().eq(Acceptance::getWorkOrderId,id).orderByAsc(Acceptance::getAcceptedAt)));}
 @Transactional public WorkOrder create(WorkOrder v){if(v.getDefectId()!=null){Defect d=defect(v.getDefectId());if(v.getDeviceId()==null)v.setDeviceId(d.getDeviceId());else if(!v.getDeviceId().equals(d.getDeviceId()))throw bad("工单设备必须与缺陷设备一致");if(orders.selectCount(Wrappers.<WorkOrder>lambdaQuery().eq(WorkOrder::getDefectId,d.getId()))>0)throw conflict("该缺陷已创建工单");if(defects.update(null,Wrappers.<Defect>lambdaUpdate().eq(Defect::getId,d.getId()).eq(Defect::getStatus,"CONFIRMED").set(Defect::getStatus,"PROCESSING"))!=1)throw conflict("只有已确认缺陷可以创建工单");if(v.getAiDiagnosisId()==null)v.setAiDiagnosisId(d.getAiDiagnosisId());}else if(v.getDeviceId()==null)throw bad("工单必须填写设备");if(!Set.of("REPAIR","PREVENTIVE","EMERGENCY").contains(v.getWorkOrderType())||!Set.of("LOW","MEDIUM","HIGH","URGENT").contains(v.getPriority()))throw bad("工单类型或优先级不正确");v.setWorkOrderCode(code("WO"));v.setCreatorUserId(current());v.setStatus("PENDING");orders.insert(v);writeLog(v.getId(),"CREATE","DRAFT","PENDING",current(),"创建并提交工单");return v;}
 @Transactional public WorkOrder assign(Long id,AssignRequest r){requireAdmin();WorkOrder o=order(id);requireMaintainerUser(r.assigneeUserId());if(orders.update(null,Wrappers.<WorkOrder>lambdaUpdate().eq(WorkOrder::getId,id).eq(WorkOrder::getStatus,"PENDING").set(WorkOrder::getAssigneeUserId,r.assigneeUserId()).set(WorkOrder::getStatus,"ASSIGNED"))!=1)throw conflict("工单状态已变化");writeLog(id,"ASSIGN","PENDING","ASSIGNED",current(),r.comment());Result<Object>x=auth.notify(new NotificationRequest(r.assigneeUserId(),"WORK_ORDER","新维修工单",o.getTitle(),"WORK_ORDER",id));if(x==null||x.code()!=0)throw new BizException(ErrorCode.SERVICE_UNAVAILABLE,"工单通知创建失败");return order(id);}
 @Transactional public WorkOrder start(Long id,String comment){requireMaintainer();WorkOrder o=order(id);requireAssignee(o);if(orders.update(null,Wrappers.<WorkOrder>lambdaUpdate().eq(WorkOrder::getId,id).eq(WorkOrder::getStatus,"ASSIGNED").eq(WorkOrder::getAssigneeUserId,current()).set(WorkOrder::getStatus,"PROCESSING").set(WorkOrder::getActualStartTime,LocalDateTime.now()))!=1)throw conflict("工单状态已变化");writeLog(id,"START","ASSIGNED","PROCESSING",current(),comment);return order(id);}
 @Transactional public WorkOrder repair(Long id,RepairRequest r){requireMaintainer();WorkOrder o=order(id);requireAssignee(o);if(!Set.of("SUCCESS","PARTIAL","FAILED").contains(r.result()))throw bad("维修结果不正确");MaintenanceRecord m=new MaintenanceRecord();m.setWorkOrderId(id);m.setDeviceId(o.getDeviceId());m.setFaultCause(r.faultCause());m.setSolution(r.solution());m.setPartsUsed(r.partsUsed());m.setDowntimeMinutes(r.downtimeMinutes());m.setMaintenanceCost(r.maintenanceCost());m.setResult(r.result());m.setRepairedBy(current());m.setRepairedAt(LocalDateTime.now());records.insert(m);if(orders.update(null,Wrappers.<WorkOrder>lambdaUpdate().eq(WorkOrder::getId,id).eq(WorkOrder::getStatus,"PROCESSING").eq(WorkOrder::getAssigneeUserId,current()).set(WorkOrder::getStatus,"WAITING_ACCEPTANCE"))!=1)throw conflict("工单状态已变化");writeLog(id,"SUBMIT_REPAIR","PROCESSING","WAITING_ACCEPTANCE",current(),r.comment());return order(id);}
 @Transactional public WorkOrder accept(Long id,AcceptanceRequest r){requireAdmin();WorkOrder o=order(id);if(Objects.equals(o.getAssigneeUserId(),current()))throw conflict("维修人不能验收自己的工单");if(!Set.of("PASSED","REJECTED").contains(r.acceptanceResult()))throw bad("验收结果不正确");boolean pass="PASSED".equals(r.acceptanceResult());String to=pass?"COMPLETED":"PROCESSING";var u=Wrappers.<WorkOrder>lambdaUpdate().eq(WorkOrder::getId,id).eq(WorkOrder::getStatus,"WAITING_ACCEPTANCE").set(WorkOrder::getStatus,to);if(pass)u.set(WorkOrder::getActualEndTime,LocalDateTime.now()).set(WorkOrder::getCloseResult,r.acceptanceContent());if(orders.update(null,u)!=1)throw conflict("工单状态已变化");Acceptance a=new Acceptance();a.setWorkOrderId(id);a.setDeviceId(o.getDeviceId());a.setAcceptanceResult(r.acceptanceResult());a.setAcceptanceContent(r.acceptanceContent());a.setAcceptedBy(current());a.setAcceptedAt(LocalDateTime.now());acceptances.insert(a);if(pass&&o.getDefectId()!=null&&defects.update(null,Wrappers.<Defect>lambdaUpdate().eq(Defect::getId,o.getDefectId()).eq(Defect::getStatus,"PROCESSING").set(Defect::getStatus,"RESOLVED").set(Defect::getResolvedAt,LocalDateTime.now()))!=1)throw conflict("关联缺陷状态已变化");writeLog(id,pass?"ACCEPT":"REJECT","WAITING_ACCEPTANCE",to,current(),r.comment());return order(id);}
 public MaintenanceHistory history(Long deviceId){return new MaintenanceHistory(deviceId,orders.selectList(Wrappers.<WorkOrder>lambdaQuery().eq(WorkOrder::getDeviceId,deviceId).orderByDesc(WorkOrder::getCreatedAt).last("LIMIT 20")),records.selectList(Wrappers.<MaintenanceRecord>lambdaQuery().eq(MaintenanceRecord::getDeviceId,deviceId).orderByDesc(MaintenanceRecord::getRepairedAt).last("LIMIT 20")),acceptances.selectList(Wrappers.<Acceptance>lambdaQuery().eq(Acceptance::getDeviceId,deviceId).orderByDesc(Acceptance::getAcceptedAt).last("LIMIT 20")));}
 private Long current(){return StpUtil.getLoginIdAsLong();}private boolean admin(){return StpUtil.hasRole("ADMIN")||StpUtil.hasRole("SUPER_ADMIN");}private boolean maintainer(){return StpUtil.hasRole("MAINTAINER");}private boolean restrictedMaintainer(){return maintainer()&&!admin();}private void requireAdmin(){if(!admin())throw forbidden("仅管理员可以执行该操作");}private void requireMaintainer(){if(!maintainer())throw forbidden("仅维修人员可以执行该操作");}private void requireDefectActor(){if(!admin()&&!maintainer())throw forbidden("当前岗位不能处理缺陷");}private void requireAssignee(WorkOrder o){if(!Objects.equals(o.getAssigneeUserId(),current()))throw forbidden("仅工单负责人可以执行该操作");}
 private void requireVisible(WorkOrder o){if(restrictedMaintainer()&&!Objects.equals(o.getAssigneeUserId(),current())&&!(Objects.equals(o.getCreatorUserId(),current())&&"PENDING".equals(o.getStatus())))throw forbidden("无权访问该工单");}private void requireMaintainerUser(Long id){if(id==null)throw bad("assigneeUserId 必填");Result<AuthClient.UserJobSummary>r=auth.job(id);if(r==null||r.code()!=0||r.data()==null||!"ENABLED".equals(r.data().status())||!r.data().roleCodes().contains("MAINTAINER"))throw bad("负责人必须是启用的维修人员");}
 private void writeLog(Long id,String action,String from,String to,Long user,String comment){WorkOrderLog l=new WorkOrderLog();l.setWorkOrderId(id);l.setAction(action);l.setFromStatus(from);l.setToStatus(to);l.setOperatorUserId(user);l.setComment(comment);logs.insert(l);}private static String code(String p){return p+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmssSSS"))+UUID.randomUUID().toString().substring(0,4).toUpperCase();}private static BizException bad(String m){return new BizException(ErrorCode.BAD_REQUEST,m);}private static BizException conflict(String m){return new BizException(ErrorCode.CONFLICT,m);}private static BizException forbidden(String m){return new BizException(ErrorCode.FORBIDDEN,m);}private static BizException notFound(String m){return new BizException(ErrorCode.NOT_FOUND,m);}private static <T> PageResult<T> page(IPage<T>p){return new PageResult<>(p.getCurrent(),p.getSize(),p.getTotal(),p.getRecords());}
}
